            font-size: 14px;
            color: var(--text-gray);
        }

        .footer-links {
            display: flex;
            gap: 24px;
        }

        .footer-links a {
            color: var(--text-gray);
            text-decoration: none;
        }

        .footer-links a:hover {
            color: var(--primary-dark);
        }

        /* Responsive */
        @media (max-width: 1024px) {
            .screenshot-grid {
                grid-template-columns: repeat(3, 1fr);
