        }

        @media (max-width: 480px) {
            .tabs {
                gap: 4px;
            }
            .tab {
                padding: 8px 12px;
                font-size: 12px;
            }
            .filter-row {
                gap: 6px;
            }
            .filter-pill {
                padding: 6px 12px;
