    <script>
        // Stats Counter Animation
        function animateCounter(element, target) {
            const duration = 2000;
            const start = 0;
            const startTime = performance.now();

            function update(currentTime) {
                const elapsed = currentTime - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const easeOut = 1 - Math.pow(1 - progress, 3);
                const current = Math.floor(start + (target - start) * easeOut);

                element.textContent = current.toLocaleString();

                if (progress < 1) {
                    requestAnimationFrame(update);
                } else {
                    element.textContent = target.toLocaleString();
                }
            }

            requestAnimationFrame(update);
        }

        // Intersection Observer for stats
        const statsSection = document.getElementById('stats');
        let statsAnimated = false;

        const statsObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting && !statsAnimated) {
                    statsAnimated = true;
                    document.querySelectorAll('.stat-number').forEach((el, index) => {
                        setTimeout(() => {
                            animateCounter(el, parseInt(el.dataset.target));
                        }, index * 150);
                    });
                }
            });
        }, { threshold: 0.5 });

        statsObserver.observe(statsSection);

        // Tab functionality
        document.querySelectorAll('.tab').forEach(tab => {
            tab.addEventListener('click', () => {
                document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
                tab.classList.add('active');

                const tabId = tab.dataset.tab;
                document.querySelectorAll('.tab-content').forEach(content => {
                    if (content.dataset.tab === tabId) {
                        content.classList.add('active');
                    } else {
                        content.classList.remove('active');
                    }
                });

                // Also update extended grid
                updateExtendedGrid(tabId, getActiveFilter());
            });
        });

        // Filter functionality
        function getActiveFilter() {
            const active = document.querySelector('.filter-pill.active');
            return active ? active.dataset.filter : 'all';
        }

        function updateExtendedGrid(tab, filter) {
            const grid = document.getElementById('extended-grid');
            const filters = {
                'all': ['Explore', 'Dashboard', 'Profile', 'Settings', 'Search', 'Notifications'],
                'profile': ['Profile View', 'Edit Profile', 'Avatar', 'Bio', 'Followers'],
                'wallet': ['Wallet Balance', 'Transactions', 'Add Funds', 'Cards', 'History'],
                'welcome': ['Welcome Screen', 'Onboarding', 'Get Started', 'Tutorial', 'Intro'],
                'account': ['Sign Up', 'Create Account', 'Verify', 'Setup', 'Register'],
                'home': ['Home Feed', 'Discover', 'Trending', 'Featured', 'Popular'],
                'subscription': ['Plans', 'Upgrade', 'Billing', 'Premium', 'Subscribe'],
                'login': ['Sign In', 'Log In', 'Password', 'Remember Me', 'Forgot'],
                'settings': ['Preferences', 'Account', 'Privacy', 'Security', 'Notifications'],
                'checkout': ['Cart', 'Payment', 'Confirm', 'Review', 'Complete'],
                'collections': ['Saved', 'Favorites', 'Lists', 'Groups', 'Archive']
